// Assemble the Larkfield Day School theme (6 Divi 5 pages for an independent primary and middle school) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php larkfield     -> dist/theme-packs/larkfield/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && LRK_DIR=<dir with the six json files> npx tsx scripts/create-larkfield-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.LRK_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/larkfield';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Larkfield Day School',
  tagline: 'Where curiosity is the curriculum.',
  audience: 'parents of children aged five to thirteen looking for a small, warm, academically serious independent school',
  conversionGoal: 'book a school tour',
  primaryCta: 'Book a tour',
  accentColorHex: '#9A3B1F',
  voice: 'warm, thoughtful and plain-spoken. Short sentences, specific details, no education jargon and no marketing superlatives.',
  palette: { primary: '#9a3b1f', secondary: '#6b645a', tint: '#faf7f2', dark: '#1c1a17', heading: '#1c1a17', body: '#6b645a' },
  designNotes: 'Editorial design language: warm paper backgrounds, Playfair Display serif headlines over Source Sans 3 body, generous whitespace, asymmetric splits and one brick-red accent.',
};

const BRAND_FACTS =
  'Larkfield Day School, 84 Maple Street, Pittsburgh, PA 15217. Phone (412) 555-0178. admissions@larkfield.school. ' +
  'Sample copy: names, fees and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'academics', roleLabel: 'Academics' },
  { role: 'admissions', roleLabel: 'Admissions' },
  { role: 'life', roleLabel: 'Student Life' },
  { role: 'about', roleLabel: 'About' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'education', style: 'editorial', color: 'red', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'larkfield-private-school-theme';
const PACK_TITLE = 'Larkfield: Private School & Education Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for an independent school, nursery, academy or tutoring centre, ready to make your ' +
  'own. Home, Academics, Admissions, Student Life, About and Contact share one calm, credible identity: warm paper ' +
  'backgrounds, a refined serif for headlines, a clean sans for reading and a single brick-red accent. Every section is ' +
  'built from proven, validated recipes and a single design language and style kit, so buttons, accordions, forms and type ' +
  'match on every page, on desktop, tablet and phone. A split hero, an at-a-glance figures band, a curriculum guide, an ' +
  'admissions timeline with tuition pricing, a student-life gallery with clubs, a school history with staff and a head\'s ' +
  'note, FAQs and a contact form with the school details are all in place. Names, fees, hours and reviews are sample copy: ' +
  'swap in your own and publish. No lorem ipsum, no broken layouts. One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Larkfield: Private School Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page Divi 5 website theme for a private school or academy: Home, Academics, Admissions, Student Life, ' +
    'About and Contact. One calm brand, real copy, admissions timeline and tuition sections.',
  keywords: [
    'divi 5 school theme', 'private school website template', 'education divi template', 'academy divi 5 theme',
    'preschool website template', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Larkfield pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
